  ('96479552-430f-5c1a-82c5-f90626c5d544', null, (select id from public.skills where slug = 'write-g10-narrative-writing'), null, 'medium',
   $q$What is the purpose of sentences 7 and 8?$q$, $q$[{"text":"They describe the concert hall so the reader can picture the audience.","is_correct":false,"misconception_token":"confuses-setting-with-conflict"},{"text":"They explain exactly how to play the solo on the D string.","is_correct":false,"misconception_token":"misidentifies-content"},{"text":"They show the narrator's doubt about the conductor's advice and remind the reader how little time is left.","is_correct":true},{"text":"They reveal that the narrator decides not to play the solo at all.","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$They show the narrator's doubt about the conductor's advice and remind the reader how little time is left.$q$, $q$Sentence 7 shows the narrator's skepticism, and sentence 8 adds urgency with "three measures." The narrator does play, as sentence 12 shows.$q$, 'draft', '037409a3-bb8c-5ebc-8dbe-cacefb12944c')
